import { sha256 } from "../../../../../application/core/agents/hash";
import { afterEach, describe, expect, it, vi } from "vitest";
import type { FileCompactionDraft } from "../../../../../domain/mapping/compaction/fileCompaction";

type SubmissionTool = { execute(id: string, draft: FileCompactionDraft): Promise<{ details: { accepted: boolean } }> };
const harness = vi.hoisted(() => ({
  create: vi.fn(),
  model: vi.fn(),
  resources: vi.fn(),
  actions: [] as ((tool: SubmissionTool) => Promise<void>)[],
  chats: [] as { prompts: string[]; abort: ReturnType<typeof vi.fn>; dispose: ReturnType<typeof vi.fn> }[]
}));
vi.mock("@earendil-works/pi-coding-agent", () => ({
  ModelRuntime: {
    create: async () => ({
      getModel: (provider: string, id: string) => {
        harness.model(provider, id); return { id };
      }, hasConfiguredAuth: () => true
    })
  },
  DefaultResourceLoader: class { constructor(options: unknown) { harness.resources(options); } async reload() { } },
  getAgentDir: () => "/tmp",
  SessionManager: { create: () => ({}) },
  SettingsManager: { inMemory: () => ({}) },
  defineTool: (tool: unknown) => tool,
  createAgentSession: async (options: { customTools: SubmissionTool[] }) => {
    harness.create(options);
    const chat = { prompts: [] as string[], abort: vi.fn(async () => { }), dispose: vi.fn() };
    harness.chats.push(chat);
    return {
      session: {
        sessionId: `chat-${harness.chats.length}`, ...chat,
        subscribe: () => () => { },
        prompt: async (text: string) => {
          chat.prompts.push(text);
          await harness.actions.shift()?.(options.customTools[0]);
        }
      }
    };
  }
}));

import { PiFileCompactionRuntime } from "../fileCompactionRuntime";

import { resolveFileCompactionSettings } from "../fileCompactionSettings";

const draft = (label = "original"): FileCompactionDraft => ({
  ascii: `source.ts\n\\-- ${label}`, mappings: [
    { treeLine: 1, sourceRanges: [{ startLine: 1, endLine: 1 }] },
    { treeLine: 2, sourceRanges: [{ startLine: 1, endLine: 1 }] }
  ]
});
const context = {
  sourceRoot: "/tmp", agent: await resolveFileCompactionSettings({
    projectId: "test", sourceFile: "source.ts", modelId: "gpt-6-astra", thinkingLevel: "high", systemPrompt: "Test base system prompt"
  }), source: {
    sourceFile: "source.ts", text: "export const a = 1;", lineCount: 1, sourceSha256: sha256("export const a = 1;")
  }
};
const step = (stepId: string) => ({ workflowId: "single-file-compaction", stepId, prompt: stepId });

afterEach(() => { harness.actions.length = 0; harness.chats.length = 0; vi.clearAllMocks(); });

describe("compaction agent session", () => {
  it("uses one chat for both turns and keeps a rejected-submission correction in that chat", async () => {
    const runtime = new PiFileCompactionRuntime(true);
    const session = await runtime.openSession(context);
    expect(harness.model).toHaveBeenCalledWith("openai-codex", "gpt-6-astra");
    expect(harness.create).toHaveBeenCalledWith(expect.objectContaining({ thinkingLevel: "high" }));
    expect(harness.resources).toHaveBeenCalledWith(expect.objectContaining({ systemPrompt: context.agent.systemPrompt.effectiveText }));
    harness.actions.push(async (tool) => {
      expect((await tool.execute("bad", { ascii: "bad", mappings: [] })).details.accepted).toBe(false);
      expect((await tool.execute("good", draft())).details.accepted).toBe(true);
    }, async (tool) => { await tool.execute("refined", draft("refined")); });
    expect((await session.runStep(step("compact"), () => { })).draft).toEqual(draft());
    expect(harness.chats[0].dispose).not.toHaveBeenCalled();
    expect((await session.runStep(step("refine"), () => { })).draft).toEqual(draft("refined"));
    expect(harness.create).toHaveBeenCalledTimes(1);
    expect(harness.chats[0].prompts).toEqual(["compact", "refine"]);
    session.dispose(); runtime.dispose();
    expect(harness.chats[0].dispose).toHaveBeenCalledTimes(1);
  });

  it("requires a new submission in the second turn", async () => {
    const runtime = new PiFileCompactionRuntime(true);
    const session = await runtime.openSession(context);
    harness.actions.push(async (tool) => { await tool.execute("first", draft()); });
    try {
      await session.runStep(step("compact"), () => { });
      await expect(session.runStep(step("refine"), () => { })).rejects.toThrow("refine finished without an accepted compaction");
    } finally { session.dispose(); runtime.dispose(); }
    expect(harness.chats[0].dispose).toHaveBeenCalledTimes(1);
  });

  it("aborts the active chat and disposes it on cancellation", async () => {
    const runtime = new PiFileCompactionRuntime(true);
    const controller = new AbortController();
    const session = await runtime.openSession({ ...context, signal: controller.signal });
    harness.actions.push(async () => { controller.abort(new Error("cancelled")); });
    try {
      await expect(session.runStep({ ...step("compact"), signal: controller.signal }, () => { })).rejects.toThrow("cancelled");
    } finally { session.dispose(); runtime.dispose(); }
    expect(harness.chats[0].abort).toHaveBeenCalledTimes(1);
    expect(harness.chats[0].dispose).toHaveBeenCalledTimes(1);
  });

  it("creates independent chats for separate workflow runs", async () => {
    const runtime = new PiFileCompactionRuntime(true);
    const first = await runtime.openSession(context);
    const second = await runtime.openSession(context);
    harness.actions.push(async (tool) => { await tool.execute("first", draft("A")); },
      async (tool) => { await tool.execute("second", draft("B")); });
    try {
      expect((await first.runStep(step("first-run"), () => { })).draft.ascii).toContain("A");
      expect((await second.runStep(step("second-run"), () => { })).draft.ascii).toContain("B");
      expect(harness.chats.map((chat) => chat.prompts)).toEqual([["first-run"], ["second-run"]]);
    } finally { first.dispose(); second.dispose(); runtime.dispose(); }
  });
});

import { Type } from "@earendil-works/pi-ai";
import { createAgentSession, DefaultResourceLoader, defineTool, getAgentDir, SettingsManager } from "@earendil-works/pi-coding-agent";
import type { FileCompactionContext, FileCompactionRuntime, FileCompactionSession } from "../../../../application/mapping/compaction/agent";
import { validateFileCompactionDraft } from "../../../../domain/mapping/compaction/validation";

import type { FileCompactionDraft } from "../../../../domain/mapping/compaction/fileCompaction";
import { createPersistedAgentSessionManager, PiAgentRuntime, progressFor } from "../../../core/agents/agentRuntime";
import { createValidatedSubmission } from "../../../core/agents/validatedSubmission";
export type { FileCompactionContext, FileCompactionRuntime, FileCompactionSession } from "../../../../application/mapping/compaction/agent";

/** One chat per workflow run; each turn gets a new submission collector. */
export class PiFileCompactionRuntime extends PiAgentRuntime implements FileCompactionRuntime {
  async openSession(context: FileCompactionContext): Promise<FileCompactionSession> {
    this.requireEnabled();
    context.signal?.throwIfAborted();
    const configured = await this.model(context.agent.modelId);
    context.signal?.throwIfAborted();
    const newSubmission = () => createValidatedSubmission<FileCompactionDraft>({
      toolName: "submit_file_compaction",
      validate: (candidate) => {
        try { validateFileCompactionDraft(candidate, context.source); }
        catch (error) { return error instanceof Error ? error.message : "Invalid compaction"; }
      },
      acceptedMessage: () => "Accepted this compaction pass."
    });
    let submission: ReturnType<typeof newSubmission> | undefined;
    const submit = defineTool({
      name: "submit_file_compaction", label: "Submit file compaction",
      description: "Submit the complete ASCII file representation with one-based inclusive source ranges for each semantic row.",
      promptSnippet: "Submit the complete mapped file compaction",
      promptGuidelines: [newSubmission().promptGuideline],
      parameters: Type.Object({
        ascii: Type.String({ minLength: 1, maxLength: 200000 }),
        mappings: Type.Array(Type.Object({
          treeLine: Type.Integer({ minimum: 1 }),
          sourceRanges: Type.Array(Type.Object({
            startLine: Type.Integer({ minimum: 1 }), endLine: Type.Integer({ minimum: 1 })
          }), { minItems: 1 })
        }), { minItems: 1 })
      }),
      execute: async (toolCallId, candidate) => {
        if (!submission) throw new Error("No compaction turn is active");
        return submission.execute(toolCallId, candidate);
      }
    });
    const settingsManager = SettingsManager.inMemory({
      defaultProvider: configured.provider,
      defaultModel: configured.modelId, defaultThinkingLevel: context.agent.thinkingLevel
    });
    const resourceLoader = new DefaultResourceLoader({
      cwd: context.sourceRoot, agentDir: getAgentDir(), settingsManager,
      noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
      systemPrompt: context.agent.systemPrompt.effectiveText
    });
    await resourceLoader.reload();
    context.signal?.throwIfAborted();
    const { session } = await createAgentSession({
      cwd: context.sourceRoot, modelRuntime: configured.runtime, model: configured.model,
      thinkingLevel: context.agent.thinkingLevel, tools: ["submit_file_compaction"], customTools: [submit],
      resourceLoader, settingsManager, sessionManager: createPersistedAgentSessionManager(context.sourceRoot)
    });
    const model = `${configured.provider}/${configured.modelId}`;
    let onProgress: ((message: string) => void) | undefined;
    const unsubscribe = session.subscribe((event) => {
      const progress = progressFor(event, model, session.sessionId);
      if (progress) onProgress?.(progress.message);
    });
    let disposed = false;
    let aborted = false;
    const abort = async () => {
      if (aborted || disposed) return;
      aborted = true;
      await session.abort().catch(() => { });
    };
    const onAbort = () => { void abort(); };
    const managed = {
      abort,
      dispose: () => {
        if (disposed) return;
        if (submission) void abort();
        disposed = true;
        context.signal?.removeEventListener("abort", onAbort);
        unsubscribe();
        session.dispose();
        this.sessions.delete(managed);
      }
    };
    this.sessions.add(managed);
    context.signal?.addEventListener("abort", onAbort, { once: true });
    if (context.signal?.aborted) {
      managed.dispose();
      context.signal.throwIfAborted();
    }
    return {
      async runStep(request, progress) {
        context.signal?.throwIfAborted();
        request.signal?.throwIfAborted();
        if (disposed || aborted) throw new Error("Compaction session is closed");
        if (submission) throw new Error("A compaction turn is already running");
        submission = newSubmission();
        onProgress = progress;
        request.signal?.addEventListener("abort", onAbort, { once: true });
        try {
          await session.prompt(request.prompt);
          context.signal?.throwIfAborted();
          request.signal?.throwIfAborted();
          if (disposed || aborted) throw new Error("Compaction session is closed");
          if (!submission.value) throw new Error(`${request.stepId} finished without an accepted compaction`);
          return { draft: submission.value, model, sessionId: session.sessionId };
        } finally {
          request.signal?.removeEventListener("abort", onAbort);
          submission = undefined;
          onProgress = undefined;
        }
      },
      dispose: managed.dispose
    };
  }
}

export class FakeFileCompactionRuntime implements FileCompactionRuntime {
  async openSession(context: FileCompactionContext): Promise<FileCompactionSession> {
    context.signal?.throwIfAborted();
    let disposed = false;
    return {
      async runStep(request, onProgress) {
        context.signal?.throwIfAborted();
        request.signal?.throwIfAborted();
        if (disposed) throw new Error("Compaction session is closed");
        onProgress(`Generating fake ${request.stepId} pass`);
        return {
          model: "fake/test", draft: {
            ascii: `${context.source.sourceFile}\n\\-- ${request.stepId === "compact" ? "Read the source snapshot" : "read(source)"}`,
            mappings: [1, 2].map((treeLine) => ({ treeLine, sourceRanges: [{ startLine: 1, endLine: context.source.lineCount }] }))
          }
        };
      },
      dispose() { disposed = true; }
    };
  }
  dispose(): void { }
}

